from itertools import combinations

x = list(map(int, input().split()))
total = sum(x)
if total % 3 != 0:
    print('N')
else:
    T = total // 3
    ok = False
    for c3 in combinations(range(6), 3):
        if sum(x[i] for i in c3) != T:
            continue
        rest = [i for i in range(6) if i not in c3]
        for c2 in combinations(rest, 2):
            if sum(x[i] for i in c2) == T:
                ok = True
                break
        if ok:
            break
    print('S' if ok else 'N')
